 1→// TranslatorsBridgeRuntime.Build.cs
 2→// Runtime module — ships in packaged builds.
 3→// Owns BridgeComponent, data types, UMG widgets, and polling-based file bridge.
 4→
 5→using UnrealBuildTool;
 6→using System.IO;
 7→
 8→public class TranslatorsBridgeRuntime : ModuleRules
 9→{
10→    public TranslatorsBridgeRuntime(ReadOnlyTargetRules Target) : base(Target)
11→    {
12→        PCHUsage = PCHUsageMode.UseExplicitOrSharedPCHs;
13→        IWYUSupport = IWYUSupportMode.Full;
14→
15→        PublicIncludePaths.AddRange(new string[]
16→        {
17→            Path.Combine(ModuleDirectory, "Public"),
18→            Path.Combine(ModuleDirectory, "Public", "UI")
19→        });
20→
21→        PrivateIncludePaths.AddRange(new string[]
22→        {
23→            Path.Combine(ModuleDirectory, "Private"),
24→            Path.Combine(ModuleDirectory, "Private", "UI")
25→        });
26→
27→        // Core runtime dependencies — ship in packaged builds
28→        PublicDependencyModuleNames.AddRange(new string[]
29→        {
30→            "Core",
31→            "CoreUObject",
32→            "Engine",
33→            "InputCore",
34→            "Json",
35→            "JsonUtilities"
36→        });
37→
38→        // UMG / Slate for gameplay widgets
39→        PublicDependencyModuleNames.AddRange(new string[]
40→        {
41→            "Slate",
42→            "SlateCore",
43→            "UMG"
44→        });
45→
46→        // HTTP for runtime Remote Control communication
47→        PrivateDependencyModuleNames.Add("HTTP");
48→
49→        // Version definition — single source of truth
50→        PublicDefinitions.Add("BRIDGE_VERSION=TEXT(\"2.1.0\")");
51→
52→        // USD support flag: editor-only via pxr, runtime uses text-based USDA parser
53→        if (Target.bBuildEditor)
54→        {
55→            PublicDefinitions.Add("WITH_USD_SUPPORT=1");
56→        }
57→        else
58→        {
59→            PublicDefinitions.Add("WITH_USD_SUPPORT=0");
60→        }
61→    }
62→}
63→

 1→// TranslatorsBridgeEditor.Build.cs
 2→// Editor module — never ships in packaged builds.
 3→// Owns DirectoryWatcher integration, MCP server lifecycle, Python bridge process,
 4→// and detail panel customizations.
 5→
 6→using UnrealBuildTool;
 7→using System.IO;
 8→
 9→public class TranslatorsBridgeEditor : ModuleRules
10→{
11→    public TranslatorsBridgeEditor(ReadOnlyTargetRules Target) : base(Target)
12→    {
13→        PCHUsage = PCHUsageMode.UseExplicitOrSharedPCHs;
14→        IWYUSupport = IWYUSupportMode.Full;
15→
16→        PublicIncludePaths.AddRange(new string[]
17→        {
18→            Path.Combine(ModuleDirectory, "Public")
19→        });
20→
21→        PrivateIncludePaths.AddRange(new string[]
22→        {
23→            Path.Combine(ModuleDirectory, "Private")
24→        });
25→
26→        // Runtime module for BridgeTypes.h and BridgeComponent access
27→        PublicDependencyModuleNames.AddRange(new string[]
28→        {
29→            "Core",
30→            "CoreUObject",
31→            "Engine",
32→            "TranslatorsBridgeRuntime"
33→        });
34→
35→        PrivateDependencyModuleNames.AddRange(new string[]
36→        {
37→            // Editor framework
38→            "UnrealEd",
39→            "EditorSubsystem",
40→            "ToolMenus",
41→            "PropertyEditor",
42→
43→            // File watching (editor-only)
44→            "DirectoryWatcher",
45→
46→            // Remote Control C++ integration (editor-only)
47→            "RemoteControl",
48→
49→            // Slate for editor UI
50→            "Slate",
51→            "SlateCore"
52→        });
53→
54→        PublicDefinitions.Add("WITH_USD_SUPPORT=1");
55→        PublicDefinitions.Add("BRIDGE_VERSION=TEXT(\"2.1.0\")");
56→    }
57→}
